      INTEGER FUNCTION IDATA(I)CC  FUNTION TO EFFECTIVELY EQUIVALENCE REAL VARIABLES IN DATA0A COMMONC  TO INTEGERS RETURNED BY THE FUNCTIONC  IDATA IS DECLARED INTEGER WITHIN THE DATA0A COMMON BLOCKCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'C      EQUIVALENCE  (FAKE,LAKE)CC--------------------------------------------------------------      FAKE = DATA(I)      IDATA = LAKE      RETURN      END